mapper.select:

select fee.* from Tran_Basic_Fee fee, Tran_Basic tb,tran_fee_def tf 
where fee.tanum=tb.tanum and fee.feeTypeID=tf .feeTypeID and tb.portfolio=#{portnum} 
and tb.ledgerDate=#{ledgerDate} and  tf.oneTimeFeeFlag=0 order by fee.feeid asc


select fee.* from Tran_Basic_Fee fee, Tran_SubRed tb,tran_fee_def tf 
where fee.tanum=tb.tanum and fee.feeTypeID=tf.feeTypeID and tb.portfolio=#{portnum} 
and tb.ledgerin=#{ledgerDate} and tf.oneTimeFeeFlag=0
